INSERT INTO docs_distribution_request_item (
    request_id, line_no, object_type, object_id, file_no,
    material_no, material_name, original_file_name, file_size, grade_cd
) VALUES (
    #{requestId}, #{lineNo}, #{objectType}, #{objectId}, #{fileNo},
    #{materialNo}, #{materialName}, #{originalFileName}, #{fileSize}, #{gradeCd}
)

mapper.select:
SELECT 
  FROM docs_distribution_request request_row
 WHERE request_row.request_id = #{value}

SELECT 
  FROM docs_distribution_request request_row
 WHERE 1 = 1

   AND request_row.requested_by_user_cd = #{requestedByUserCd}


   AND request_row.status = #{status}


   AND request_row.status = 'PENDING_APPROVAL'


   AND request_row.status = 'APPROVED'

 ORDER BY request_row.updated_at DESC, request_row.request_id DESC
 LIMIT #{limit} OFFSET #{offset}
